 "startDate": "2000-12-25",
 "endDate": "2000-12-31",
 "format": "CSV"
}" headers = { 'authorization': "Bearer XXXXX", 'content-type': "application/json", 'cache-control': "no-cache", 'postman-token': "XXX" } response = requests.request("POST", url, data=payload, headers=headers) print(response.text) I have tried to execute after removing postman-token also but still getting below error: {"message":"Internal Server Error: correlationId=V2-ee8fb1b098490b8665dd936e8472978b","type":"error","code":1}

reference_answer:
When using passing json data in requests , you can pass a dictionary instead of string. You can try this: import requests import json url = "http://services.XXX.com/rest/v2/verification" payload = "{
 "startDate": "2000-12-25",
 "endDate": "2000-12-31",
 "format": "CSV"
}" headers = { 'authorization': "Bearer XXXXX", 'content-type': "application/json", 'cache-control': "no-cache", 'postman-token': "XXX" } response = requests.post(url,json=json.loads(payload),headers=headers) print(response.text)

